import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    include: ['src/**/*.test.ts'],
    globals: false,
  },
});

import { describe, it, expect } from 'vitest';
import { readFile } from 'node:fs/promises';
import { readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { parse } from 'yaml';
import { InstinctLoader } from '../engine/instinct-loader.js';

/**
 * CI guard for the YAML validity defect documented in
 * HANDOFF-learned-instincts-yaml-repair.md.
 *
 * Free-text fields (`rule`, `value`, `rationale`) written as plain (unquoted)
 * scalars break a strict parser when their text contains `": "` or a trailing
 * colon followed by an indented continuation line. The runtime writer
 * (`InstinctLoader.save` -> `yaml.stringify`) emits safe block/quoted scalars,
 * but hand-edits and the /instill fallback path can reintroduce the defect.
 *
 * These tests fail CI the moment any shipped `*.instincts.yaml` stops parsing,
 * so a silent injection-stopping parse failure can never ship unnoticed.
 */
const instinctsDir = resolve(dirname(fileURLToPath(import.meta.url)), '../../instincts');

const yamlFiles = readdirSync(instinctsDir).filter((f) => f.endsWith('.instincts.yaml'));

describe('shipped instinct YAML files are valid', () => {
  it('discovers at least one instinct file', () => {
    expect(yamlFiles.length).toBeGreaterThan(0);
  });

  it.each(yamlFiles)('%s parses under strict yaml.parse', async (file) => {
    const raw = await readFile(join(instinctsDir, file), 'utf-8');
    expect(() => parse(raw)).not.toThrow();
  });

  it.each(yamlFiles)('%s loads + validates through InstinctLoader', async (file) => {
    const loader = new InstinctLoader(instinctsDir);
    const loaded = await loader.load(file);
    expect(loaded.instincts).toBeDefined();
  });
});

import { describe, it, expect } from 'vitest';
import { ContextSchema, ContextMetadataSchema, StoreTriggerSchema } from '../schema/context.schema.js';

describe('ContextMetadataSchema', () => {
  it('accepts valid metadata', () => {
    const meta = {
      version: '1.0.0',
      applies_to_tools: ['git:*'],
      priority: 'high' as const,
    };
    expect(ContextMetadataSchema.safeParse(meta).success).toBe(true);
  });

  it('rejects empty applies_to_tools', () => {
    const bad = { version: '1.0.0', applies_to_tools: [] };
    expect(ContextMetadataSchema.safeParse(bad).success).toBe(false);
  });

  it('accepts valid inheritance values', () => {
    const meta = {
      version: '1.0.0',
      applies_to_tools: ['*'],
      inheritance: 'fallback_for_unspecified_tools' as const,
    };
    expect(ContextMetadataSchema.safeParse(meta).success).toBe(true);
  });
});

describe('StoreTriggerSchema', () => {
  it('accepts valid store trigger', () => {
    const trigger = {
      patterns: ['git commit', 'git push'],
      action: 'store_with_metadata',
      tags: ['git', 'version-control'],
      priority: 'high' as const,
      confidence_threshold: 0.8,
    };
    expect(StoreTriggerSchema.safeParse(trigger).success).toBe(true);
  });

  it('rejects empty patterns', () => {
    const bad = { patterns: [], action: 'store', tags: ['git'] };
    expect(StoreTriggerSchema.safeParse(bad).success).toBe(false);
  });
});

describe('ContextSchema', () => {
  const validContext = {
    tool_category: 'git',
    description: 'Git-specific context rules',
    auto_convert: true,
    metadata: {
      version: '1.0.0',
      applies_to_tools: ['git:*', 'bash:git'],
    },
  };

  it('accepts a minimal valid context', () => {
    expect(ContextSchema.safeParse(validContext).success).toBe(true);
  });

  it('defaults auto_convert to false', () => {
    const noConvert = { ...validContext, auto_convert: undefined };
    const result = ContextSchema.safeParse(noConvert);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.auto_convert).toBe(false);
    }
  });

  it('accepts context with triggers', () => {
    const withTriggers = {
      ...validContext,
      auto_store_triggers: {
        git_commands: {
          patterns: ['git add', 'git commit'],
          action: 'store_with_metadata',
          tags: ['git'],
        },
      },
      auto_retrieve_triggers: {
        git_help: {
          patterns: ['how to.*git'],
          action: 'search_and_suggest',
          search_tags: ['git'],
        },
      },
    };
    expect(ContextSchema.safeParse(withTriggers).success).toBe(true);
  });

  it('accepts context with auto_corrections', () => {
    const withCorrections = {
      ...validContext,
      auto_corrections: {
        fix_prefix: {
          pattern: '^(Fix|FIX)\\s*:?\\s*(.+)',
          replacement: 'fix: $2',
        },
      },
    };
    expect(ContextSchema.safeParse(withCorrections).success).toBe(true);
  });

  it('passes through unknown domain-specific sections', () => {
    const withCustom = {
      ...validContext,
      workflow_patterns: { gitflow: { main_branches: ['main'] } },
      best_practices: { commits: { atomic: true } },
      custom_section: { foo: 'bar' },
    };
    const result = ContextSchema.safeParse(withCustom);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.custom_section).toEqual({ foo: 'bar' });
    }
  });

  it('rejects missing tool_category', () => {
    const { tool_category: _, ...bad } = validContext;
    expect(ContextSchema.safeParse(bad).success).toBe(false);
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtemp, rm, writeFile, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { stringify, parse } from 'yaml';
import { Registry } from '../cli/registry.js';
import type { Instinct, InstinctFile } from '../types/instinct.js';

let storeDir: string;
let sourceDir: string;
let registry: Registry;

function instinct(id: string, rule: string): Instinct {
  return {
    id,
    rule,
    domain: 'testing',
    tags: ['testing'],
    trigger_patterns: [id],
    confidence: 0.7,
    min_confidence: 0.5,
    usage_count: 0,
    approved_by: 'human',
    active: true,
    outcome_log: [],
  };
}

const store: InstinctFile = {
  version: '1.0',
  instincts: {
    'already-here': instinct(
      'already-here',
      'This instinct already lives in the target store and must not be overwritten',
    ),
  },
};

beforeEach(async () => {
  storeDir = await mkdtemp(join(tmpdir(), 'mcp-cp-store-'));
  sourceDir = await mkdtemp(join(tmpdir(), 'mcp-cp-source-'));
  await writeFile(
    join(storeDir, 'learned.instincts.yaml'),
    stringify(store),
    'utf-8',
  );
  registry = new Registry(storeDir);
});

afterEach(async () => {
  await rm(storeDir, { recursive: true, force: true });
  await rm(sourceDir, { recursive: true, force: true });
});

describe('Registry.importFrom', () => {
  it('adds instincts that are not yet in the store', async () => {
    const src = join(sourceDir, 'other.instincts.yaml');
    await writeFile(
      src,
      stringify({
        version: '1.0',
        instincts: {
          'brand-new': instinct(
            'brand-new',
            'A brand new instinct that should be merged into the target store',
          ),
        },
      }),
      'utf-8',
    );

    const result = await registry.importFrom(src);
    expect(result.added).toEqual(['brand-new']);
    expect(result.skipped).toEqual([]);

    const found = await registry.find('brand-new');
    expect(found).not.toBeNull();
  });

  it('skips ids that already exist and leaves them untouched', async () => {
    const src = join(sourceDir, 'other.instincts.yaml');
    await writeFile(
      src,
      stringify({
        version: '1.0',
        instincts: {
          'already-here': instinct(
            'already-here',
            'A conflicting rule text that must never replace the stored version',
          ),
        },
      }),
      'utf-8',
    );

    const result = await registry.importFrom(src);
    expect(result.added).toEqual([]);
    expect(result.skipped).toEqual(['already-here']);

    const found = await registry.find('already-here');
    expect(found!.instinct.rule).toBe(store.instincts['already-here']!.rule);
  });

  it('ignores ids that live in a non-canonical file — those are not in the store', async () => {
    await writeFile(
      join(storeDir, 'other-store-file.instincts.yaml'),
      stringify({
        version: '1.0',
        instincts: {
          elsewhere: instinct(
            'elsewhere',
            'Lives in a second file of the target store and must still be detected',
          ),
        },
      }),
      'utf-8',
    );
    const src = join(sourceDir, 'in.instincts.yaml');
    await writeFile(
      src,
      stringify({
        version: '1.0',
        instincts: {
          elsewhere: instinct(
            'elsewhere',
            'Duplicate of an instinct stored in a different file of the store',
          ),
        },
      }),
      'utf-8',
    );

    const result = await registry.importFrom(src);
    expect(result.added).toEqual(['elsewhere']);
    expect(result.skipped).toEqual([]);
  });

  it('imports legacy top-level array files via loader repair', async () => {
    const src = join(sourceDir, 'legacy.instincts.yaml');
    await writeFile(
      src,
      stringify([
        instinct(
          'legacy-entry',
          'A legacy array-shaped instinct file as written by older instill versions',
        ),
      ]),
      'utf-8',
    );

    const result = await registry.importFrom(src);
    expect(result.added).toEqual(['legacy-entry']);
    expect(result.repairs.length).toBeGreaterThan(0);
  });

  it('always writes into the canonical store file', async () => {
    const src = join(sourceDir, 'in.instincts.yaml');
    await writeFile(
      src,
      stringify({
        version: '1.0',
        instincts: {
          targeted: instinct(
            'targeted',
            'Should land in the canonical store file regardless of the source name',
          ),
        },
      }),
      'utf-8',
    );

    const result = await registry.importFrom(src);
    expect(result.target).toBe('learned.instincts.yaml');
    const raw = await readFile(join(storeDir, 'learned.instincts.yaml'), 'utf-8');
    const parsed = parse(raw) as InstinctFile;
    expect(Object.keys(parsed.instincts).sort()).toEqual(['already-here', 'targeted']);
  });

  it('creates the store file when it does not exist yet', async () => {
    const emptyStore = await mkdtemp(join(tmpdir(), 'mcp-cp-empty-'));
    const fresh = new Registry(emptyStore);
    const src = join(sourceDir, 'in.instincts.yaml');
    await writeFile(
      src,
      stringify({
        version: '1.0',
        instincts: {
          first: instinct(
            'first',
            'First instinct imported into a completely empty target store',
          ),
        },
      }),
      'utf-8',
    );

    const result = await fresh.importFrom(src);
    expect(result.added).toEqual(['first']);
    expect((await fresh.find('first'))!.instinct.id).toBe('first');
    await rm(emptyStore, { recursive: true, force: true });
  });

  it('reports a dry run without writing', async () => {
    const src = join(sourceDir, 'in.instincts.yaml');
    await writeFile(
      src,
      stringify({
        version: '1.0',
        instincts: {
          'dry-run': instinct(
            'dry-run',
            'Should be reported as importable but never written to disk in dry run',
          ),
        },
      }),
      'utf-8',
    );

    const result = await registry.importFrom(src, { dryRun: true });
    expect(result.added).toEqual(['dry-run']);
    expect(await registry.find('dry-run')).toBeNull();
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { stringify } from 'yaml';
import { Engine } from '../engine/engine.js';
import { Registry } from '../cli/registry.js';
import { CANONICAL_INSTINCTS_FILE } from '../config/paths.js';
import type { Instinct } from '../types/instinct.js';

/**
 * The store has exactly one source of truth. Extra *.instincts.yaml files in
 * the store directory are never merged in silently — they are reported by name
 * so they can be merged deliberately with `mcp-cp import`.
 */

let dir: string;

function instinct(id: string): Instinct {
  return {
    id,
    rule: 'A placeholder rule long enough to satisfy the schema token range check',
    domain: 'testing',
    tags: ['testing'],
    trigger_patterns: [id],
    confidence: 0.7,
    min_confidence: 0.5,
    usage_count: 0,
    approved_by: 'human',
    active: true,
    outcome_log: [],
  };
}

async function writeStore(name: string, ids: string[]): Promise<void> {
  await writeFile(
    join(dir, name),
    stringify({
      version: '1.0',
      instincts: Object.fromEntries(ids.map((id) => [id, instinct(id)])),
    }),
    'utf-8',
  );
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'mcp-cp-single-'));
});

afterEach(async () => {
