import { describe, it, expect } from 'vitest';
import { ContextMatcher } from '../engine/context-matcher.js';
import type { Context } from '../types/context.js';

function makeContexts(): Map<string, Context> {
  const map = new Map<string, Context>();

  map.set('git', {
    tool_category: 'git',
    description: 'Git-specific context rules',
    auto_convert: true,
    metadata: {
      version: '1.0.0',
      applies_to_tools: ['git:*', 'bash:git'],
      priority: 'high',
    },
    auto_corrections: {
      fix_prefix: { pattern: '^Fix\\s', replacement: 'fix: ' },
    },
  } as Context);

  map.set('general', {
    tool_category: 'general',
    description: 'General preferences',
    auto_convert: false,
    metadata: {
      version: '1.0.0',
      applies_to_tools: ['*'],
      priority: 'low',
      inheritance: 'fallback_for_unspecified_tools' as const,
    },
  } as Context);

  map.set('memory', {
    tool_category: 'memory',
    description: 'Memory service rules',
    auto_convert: false,
    metadata: {
      version: '1.0.0',
      applies_to_tools: ['memory', 'mcp-memory'],
      priority: 'high',
    },
  } as Context);

  map.set('docker', {
    tool_category: 'docker',
    description: 'Docker rules',
    auto_convert: false,
    metadata: {
      version: '1.0.0',
      applies_to_tools: ['docker:*'],
      priority: 'medium',
    },
  } as Context);

  return map;
}

describe('ContextMatcher', () => {
  const matcher = new ContextMatcher();

  it('matches wildcard (*) pattern', () => {
    const contexts = makeContexts();
    const matches = matcher.match(contexts, { tool: 'random-tool' });

    expect(matches.some((m) => m.context.tool_category === 'general')).toBe(true);
  });

  it('matches prefix wildcard (git:*)', () => {
    const contexts = makeContexts();
    const matches = matcher.match(contexts, { tool: 'git:commit' });

    expect(matches.some((m) => m.context.tool_category === 'git')).toBe(true);
  });

  it('matches exact tool name (bash:git)', () => {
    const contexts = makeContexts();
    const matches = matcher.match(contexts, { tool: 'bash:git' });

    expect(matches.some((m) => m.context.tool_category === 'git')).toBe(true);
  });

  it('matches category-level (memory matches memory:search)', () => {
    const contexts = makeContexts();
    const matches = matcher.match(contexts, { tool: 'memory:search' });

    expect(matches.some((m) => m.context.tool_category === 'memory')).toBe(true);
  });

  it('sorts by priority (high before low)', () => {
    const contexts = makeContexts();
    const matches = matcher.match(contexts, { tool: 'git:commit' });

    const gitIdx = matches.findIndex((m) => m.context.tool_category === 'git');
    const genIdx = matches.findIndex((m) => m.context.tool_category === 'general');

    expect(gitIdx).toBeLessThan(genIdx);
  });

  it('filters by min_priority', () => {
    const contexts = makeContexts();
    const matches = matcher.match(contexts, {
      tool: 'git:commit',
      min_priority: 'high',
    });

    expect(matches.every((m) => m.priority === 'high')).toBe(true);
    expect(matches.some((m) => m.context.tool_category === 'general')).toBe(false);
  });

  it('filters by categories', () => {
    const contexts = makeContexts();
    const matches = matcher.match(contexts, {
      tool: 'git:commit',
      categories: ['git'],
    });

    expect(matches.every((m) => m.context.tool_category === 'git')).toBe(true);
  });

  it('returns auto-corrections for matching tool', () => {
    const contexts = makeContexts();
    const corrections = matcher.getAutoCorrections(contexts, 'git:commit');

    expect(corrections.length).toBeGreaterThan(0);
    expect(corrections[0]!.name).toBe('fix_prefix');
  });

  it('skips auto-corrections when auto_convert is false', () => {
    const contexts = makeContexts();
    const corrections = matcher.getAutoCorrections(contexts, 'memory:store');

    // Memory context has auto_convert: false, general has no corrections
    const memoryCorrections = corrections.filter((c) => c.name.includes('memory'));
    expect(memoryCorrections).toEqual([]);
  });
});

import { describe, it, expect } from 'vitest';
import { InstinctSchema, InstinctFileSchema, InstinctCandidateSchema } from '../schema/instinct.schema.js';

describe('InstinctSchema', () => {
  const validInstinct = {
    id: 'git-conventional-commits',
    rule: 'Use conventional commit prefixes feat fix chore docs refactor test ci for all commit messages',
    domain: 'git',
    tags: ['git', 'commits'],
    trigger_patterns: ['git commit', 'commit message'],
    confidence: 0.85,
    min_confidence: 0.5,
    usage_count: 12,
    approved_by: 'human' as const,
    outcome_log: [],
  };

  it('accepts a valid instinct', () => {
    const result = InstinctSchema.safeParse(validInstinct);
    expect(result.success).toBe(true);
  });

  it('applies defaults for optional fields', () => {
    const minimal = {
      id: 'test-rule',
      rule: 'Always run tests before committing code to the repository branch',
      domain: 'testing',
      tags: ['test'],
      trigger_patterns: ['test'],
      confidence: 0.7,
      approved_by: 'human' as const,
    };

    const result = InstinctSchema.safeParse(minimal);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.min_confidence).toBe(0.5);
      expect(result.data.usage_count).toBe(0);
      expect(result.data.outcome_log).toEqual([]);
      expect(result.data.active).toBe(true);
    }
  });

  it('rejects invalid id format (must be kebab-case)', () => {
    const bad = { ...validInstinct, id: 'NotKebab' };
    const result = InstinctSchema.safeParse(bad);
    expect(result.success).toBe(false);
  });

  it('rejects single-char id', () => {
    const bad = { ...validInstinct, id: 'x' };
    const result = InstinctSchema.safeParse(bad);
    expect(result.success).toBe(false);
  });

  it('rejects confidence outside 0-1 range', () => {
    const tooHigh = { ...validInstinct, confidence: 1.5 };
    expect(InstinctSchema.safeParse(tooHigh).success).toBe(false);

    const tooLow = { ...validInstinct, confidence: -0.1 };
    expect(InstinctSchema.safeParse(tooLow).success).toBe(false);
  });

  it('rejects rule that is too short (< 5 tokens)', () => {
    const bad = { ...validInstinct, rule: 'Use tabs' };
    const result = InstinctSchema.safeParse(bad);
    expect(result.success).toBe(false);
  });

  it('rejects empty tags array', () => {
    const bad = { ...validInstinct, tags: [] };
    expect(InstinctSchema.safeParse(bad).success).toBe(false);
  });

  it('rejects empty trigger_patterns array', () => {
    const bad = { ...validInstinct, trigger_patterns: [] };
    expect(InstinctSchema.safeParse(bad).success).toBe(false);
  });

  it('rejects min_confidence exceeding confidence', () => {
    const bad = { ...validInstinct, confidence: 0.3, min_confidence: 0.8 };
    const result = InstinctSchema.safeParse(bad);
    expect(result.success).toBe(false);
  });

  it('accepts valid outcome_log entries', () => {
    const withOutcomes = {
      ...validInstinct,
      outcome_log: [
        {
          timestamp: '2026-03-07T18:30:00Z',
          result: 'positive' as const,
          delta_confidence: 0.05,
          note: 'Worked well',
        },
        {
          timestamp: '2026-03-07T19:00:00Z',
          result: 'negative' as const,
          delta_confidence: -0.1,
        },
      ],
    };
    expect(InstinctSchema.safeParse(withOutcomes).success).toBe(true);
  });

  it('rejects invalid approved_by value', () => {
    const bad = { ...validInstinct, approved_by: 'bot' };
    expect(InstinctSchema.safeParse(bad).success).toBe(false);
  });
});

