        'utf-8',
      );
      const { entries, skipped, unloadedFiles } = await registry.listAll();
      expect(entries).toHaveLength(2);          // canonical file still loaded
      expect(skipped).toHaveLength(0);          // the extra file is not even parsed
      expect(unloadedFiles).toEqual(['broken.instincts.yaml']);
    });
  });

  describe('find', () => {
    it('finds an instinct by id', async () => {
      const result = await registry.find('test-rule');
      expect(result).not.toBeNull();
      expect(result!.instinct.id).toBe('test-rule');
    });

    it('returns null for non-existent id', async () => {
      const result = await registry.find('nonexistent');
      expect(result).toBeNull();
    });
  });

  describe('approve', () => {
    it('sets approved_by to human and activates', async () => {
      const inst = await registry.approve('test-rule');
      expect(inst.approved_by).toBe('human');
      expect(inst.active).toBe(true);
      expect(inst.updated_at).toBeDefined();

      // Verify persisted
      const reloaded = await registry.find('test-rule');
      expect(reloaded!.instinct.approved_by).toBe('human');
    });

    it('throws for non-existent id', async () => {
      await expect(registry.approve('nope')).rejects.toThrow('not found');
    });
  });

  describe('reject', () => {
    it('deactivates and reduces confidence', async () => {
      const inst = await registry.reject('test-rule');
      expect(inst.active).toBe(false);
      expect(inst.confidence).toBeLessThan(0.7);
      expect(inst.outcome_log).toHaveLength(1);
      expect(inst.outcome_log[0]!.result).toBe('negative');
    });

    it('floors confidence at 0', async () => {
      // Reject twice
      await registry.reject('docker-multi'); // 0.6 - 0.3 = 0.3
      const inst = await registry.reject('docker-multi'); // 0.3 - 0.3 = 0.0
      expect(inst.confidence).toBe(0);
    });
  });

  describe('tune', () => {
    it('updates confidence', async () => {
      const inst = await registry.tune('test-rule', { confidence: 0.95 });
      expect(inst.confidence).toBe(0.95);
    });

    it('updates rule text', async () => {
      const inst = await registry.tune('test-rule', {
        rule: 'Always run vitest before committing TypeScript code to the repository safely',
      });
      expect(inst.rule).toContain('vitest');
    });

    it('updates tags', async () => {
      const inst = await registry.tune('test-rule', {
        tags: ['testing', 'vitest', 'ci-cd'],
      });
      expect(inst.tags).toContain('vitest');
    });

    it('activates/deactivates', async () => {
      const deactivated = await registry.tune('test-rule', { active: false });
      expect(deactivated.active).toBe(false);

      const reactivated = await registry.tune('test-rule', { active: true });
      expect(reactivated.active).toBe(true);
    });
  });

  describe('recordOutcome', () => {
    it('records positive outcome and increases confidence', async () => {
      const inst = await registry.recordOutcome('test-rule', 'positive', 0.05, 'It worked');
      expect(inst.confidence).toBeCloseTo(0.75);
      expect(inst.outcome_log).toHaveLength(1);
      expect(inst.outcome_log[0]!.result).toBe('positive');
      expect(inst.outcome_log[0]!.note).toBe('It worked');
    });

    it('records negative outcome and decreases confidence', async () => {
      const inst = await registry.recordOutcome('test-rule', 'negative', -0.1);
      expect(inst.confidence).toBeCloseTo(0.6);
    });

    it('clamps confidence to [0, 1]', async () => {
      const inst = await registry.recordOutcome('test-rule', 'positive', 0.5);
      expect(inst.confidence).toBeLessThanOrEqual(1);
    });
  });

  describe('remove', () => {
    it('deletes an instinct', async () => {
      await registry.remove('test-rule');
      const result = await registry.find('test-rule');
      expect(result).toBeNull();

      // Other instincts still exist
      const { entries: remaining } = await registry.listAll();
      expect(remaining).toHaveLength(1);
    });

    it('throws for non-existent id', async () => {
      await expect(registry.remove('nope')).rejects.toThrow('not found');
    });
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtemp, rm, readFile, writeFile, stat } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { parse } from 'yaml';
import { InstinctLoader } from '../engine/instinct-loader.js';

/**
 * Regression tests for issue #10:
 * /instill skill used to write top-level YAML arrays, which the strict Zod
 * schema silently rejected. The loader now detects AND auto-corrects those
 * files — converting shape, synthesizing missing ids, resolving collisions —
 * and can persist the canonical form back to disk with a `.bak` of the
 * original via `loader.repair(filename)`.
 */
describe('InstinctLoader — auto-repair', () => {
  let dir: string;
  let loader: InstinctLoader;

  beforeEach(async () => {
    dir = await mkdtemp(join(tmpdir(), 'mcp-cp-loader-'));
    loader = new InstinctLoader(dir);
  });

  afterEach(async () => {
    await rm(dir, { recursive: true, force: true });
  });

  const validRule =
    'Always prefer named exports over default exports in TypeScript modules for clarity';

  const legacyArrayEntry = (id: string, domain = 'typescript') => `
- id: ${id}
  rule: "${validRule}"
  domain: ${domain}
  tags: [${domain}, style]
  trigger_patterns:
    - "export default"
  confidence: 0.8
  min_confidence: 0.5
  approved_by: human
  active: true
  outcome_log: []
`;

  // -------------------------------------------------------------------------
  // Happy path
  // -------------------------------------------------------------------------

  it('accepts canonical object form without repairs', async () => {
    const yaml = `
version: "1.0"
instincts:
  named-exports:
    id: named-exports
    rule: "${validRule}"
    domain: typescript
    tags: [typescript, style]
    trigger_patterns: ["export default"]
    confidence: 0.8
    min_confidence: 0.5
    approved_by: human
    active: true
    outcome_log: []
`;
    await writeFile(join(dir, 'canonical.instincts.yaml'), yaml);
    const { file, repairs } = await loader.loadWithRepairs(
      'canonical.instincts.yaml',
    );
    expect(file.version).toBe('1.0');
    expect(Object.keys(file.instincts)).toEqual(['named-exports']);
    expect(repairs).toEqual([]);
  });

  // -------------------------------------------------------------------------
  // Shape normalization
  // -------------------------------------------------------------------------

  it('normalizes legacy array form into object form (issue #10)', async () => {
    const yaml =
      legacyArrayEntry('named-exports') +
      legacyArrayEntry('prefer-const', 'javascript');
    await writeFile(join(dir, 'legacy.instincts.yaml'), yaml);

    const { file, repairs } = await loader.loadWithRepairs(
      'legacy.instincts.yaml',
    );

    expect(file.version).toBe('1.0');
    expect(Object.keys(file.instincts).sort()).toEqual([
      'named-exports',
      'prefer-const',
    ]);
    expect(repairs.some((r) => r.kind === 'shape_array_to_object')).toBe(true);
  });

  // -------------------------------------------------------------------------
  // ID synthesis
  // -------------------------------------------------------------------------

  it('synthesizes kebab-case ids from rule text when missing', async () => {
    const yaml = `
- rule: "${validRule}"
  domain: typescript
  tags: [typescript]
  trigger_patterns: ["export default"]
  confidence: 0.8
  approved_by: human
`;
    await writeFile(join(dir, 'no-id.instincts.yaml'), yaml);
    const { file, repairs } = await loader.loadWithRepairs(
      'no-id.instincts.yaml',
    );

    // Slug: first 4 words of "Always prefer named exports..." → "always-prefer-named-exports"
    expect(Object.keys(file.instincts)).toEqual(['always-prefer-named-exports']);
    expect(repairs.some((r) => r.kind === 'id_synthesized')).toBe(true);
  });

  it('resolves id collisions with numeric suffixes', async () => {
    const yaml = `
- id: named-exports
  rule: "${validRule}"
  domain: typescript
  tags: [typescript]
  trigger_patterns: ["export default"]
  confidence: 0.8
  approved_by: human
- id: named-exports
  rule: "${validRule}"
  domain: javascript
  tags: [javascript]
  trigger_patterns: ["export default"]
  confidence: 0.7
  approved_by: human
`;
    await writeFile(join(dir, 'collision.instincts.yaml'), yaml);
    const { file, repairs } = await loader.loadWithRepairs(
      'collision.instincts.yaml',
    );

    expect(Object.keys(file.instincts).sort()).toEqual([
      'named-exports',
      'named-exports-2',
    ]);
    expect(repairs.some((r) => r.kind === 'id_collision_resolved')).toBe(true);
  });

  it('skips entries whose rule is too short to slug', async () => {
    const yaml = `
- rule: "a"
  domain: test
  tags: [test]
  trigger_patterns: ["x"]
  confidence: 0.8
  approved_by: human
- id: real-one
  rule: "${validRule}"
  domain: typescript
  tags: [typescript]
  trigger_patterns: ["export default"]
  confidence: 0.8
  approved_by: human
`;
    await writeFile(join(dir, 'short.instincts.yaml'), yaml);
    const { file, repairs } = await loader.loadWithRepairs(
      'short.instincts.yaml',
    );
    expect(Object.keys(file.instincts)).toEqual(['real-one']);
    expect(repairs.some((r) => r.kind === 'entry_skipped')).toBe(true);
  });

  // -------------------------------------------------------------------------
  // Content validation still enforced
  // -------------------------------------------------------------------------

  it('normalizes an instincts: array under a top-level key (issue #1)', async () => {
    // Shape produced by some /instill runs: canonical wrapper key, but the
    // instincts value is a list instead of a map keyed by id.
    const yaml = `instincts:
${legacyArrayEntry('nested-array-entry')
  .split('\n')
  .map((l) => (l ? `  ${l}` : l))
  .join('\n')}
`;
    await writeFile(join(dir, 'nested.instincts.yaml'), yaml, 'utf-8');

    const { file, repairs } = await loader.loadWithRepairs('nested.instincts.yaml');
    expect(file.version).toBe('1.0');
    expect(Object.keys(file.instincts)).toEqual(['nested-array-entry']);
    expect(repairs.map((r) => r.kind)).toContain('shape_array_to_object');
  });

  it('defaults a missing or unknown version to "1.0"', async () => {
    const yaml = `version: "0.9"
instincts:
  named-exports:
    id: named-exports
    rule: "${validRule}"
    domain: typescript
    tags: [typescript]
    trigger_patterns: ["export default"]
    confidence: 0.8
    min_confidence: 0.5
    approved_by: human
    active: true
    outcome_log: []
`;
    await writeFile(join(dir, 'oldver.instincts.yaml'), yaml, 'utf-8');

    const { file, repairs } = await loader.loadWithRepairs('oldver.instincts.yaml');
    expect(file.version).toBe('1.0');
    expect(repairs.map((r) => r.kind)).toContain('version_normalized');
  });

  it('still rejects content-invalid instincts after shape repair', async () => {
    // Array form but the rule is too short (Zod: 5–120 token soft range)
    const yaml = `
- id: too-short
  rule: "tiny rule"
  domain: test
  tags: [test]
  trigger_patterns: ["x"]
  confidence: 0.8
  approved_by: human
`;
    await writeFile(join(dir, 'bad.instincts.yaml'), yaml);
    await expect(loader.load('bad.instincts.yaml')).rejects.toThrow();
  });

  // -------------------------------------------------------------------------
  // Persistent repair
  // -------------------------------------------------------------------------

  it('repair() writes canonical form + keeps .bak of original', async () => {
    const original = legacyArrayEntry('named-exports');
    await writeFile(join(dir, 'persist.instincts.yaml'), original);

    const repairs = await loader.repair('persist.instincts.yaml');
    expect(repairs.length).toBeGreaterThan(0);

    // .bak holds original text
    const bak = await readFile(join(dir, 'persist.instincts.yaml.bak'), 'utf-8');
    expect(bak).toBe(original);

    // New file is canonical object form
    const rewritten = await readFile(join(dir, 'persist.instincts.yaml'), 'utf-8');
    const parsed = parse(rewritten) as { version: string; instincts: Record<string, unknown> };
    expect(parsed.version).toBe('1.0');
    expect(Object.keys(parsed.instincts)).toEqual(['named-exports']);

    // Second repair is a no-op (already canonical)
    const second = await loader.repair('persist.instincts.yaml');
    expect(second).toEqual([]);
  });

  it('repair() is a no-op when file is already canonical (no .bak created)', async () => {
    const yaml = `
version: "1.0"
instincts:
  named-exports:
    id: named-exports
    rule: "${validRule}"
    domain: typescript
    tags: [typescript]
    trigger_patterns: ["export default"]
    confidence: 0.8
    min_confidence: 0.5
    approved_by: human
    active: true
    outcome_log: []
`;
    await writeFile(join(dir, 'clean.instincts.yaml'), yaml);
    const repairs = await loader.repair('clean.instincts.yaml');
    expect(repairs).toEqual([]);

    await expect(stat(join(dir, 'clean.instincts.yaml.bak'))).rejects.toThrow();
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtemp, mkdir, rm, stat, writeFile, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { stringify } from 'yaml';
import { InstinctLoader } from '../engine/instinct-loader.js';
import type { Instinct } from '../types/instinct.js';

/**
 * A store that exists on disk must never be replaced by an empty one.
 *
 * `append()` used to fall back to `{version, instincts:{}}` whenever the load
 * threw — for any reason, including a transient parse failure on a perfectly
 * good file — and then saved that empty file over the real one. A 232-instinct
 * store was wiped down to a single entry that way.
 */

let dir: string;
let loader: InstinctLoader;

function instinct(id: string): Instinct {
  return {
    id,
    rule: 'A placeholder rule long enough to satisfy the schema token range check',
    domain: 'testing',
    tags: ['testing'],
    trigger_patterns: [id],
    confidence: 0.7,
    min_confidence: 0.5,
    usage_count: 0,
    approved_by: 'human',
    active: true,
    outcome_log: [],
  };
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'mcp-cp-durability-'));
  loader = new InstinctLoader(dir);
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

describe('InstinctLoader.append — never destroys an existing store', () => {
  it('creates the file when it does not exist yet', async () => {
    const file = await loader.append('learned.instincts.yaml', instinct('first-one'));
    expect(Object.keys(file.instincts)).toEqual(['first-one']);
  });

  it('appends to an existing store without dropping its entries', async () => {
    await writeFile(
      join(dir, 'learned.instincts.yaml'),
      stringify({ version: '1.0', instincts: { existing: instinct('existing') } }),
      'utf-8',
    );

    const file = await loader.append('learned.instincts.yaml', instinct('added'));
    expect(Object.keys(file.instincts).sort()).toEqual(['added', 'existing']);
  });

  it('throws instead of overwriting when the existing file cannot be parsed', async () => {
    const path = join(dir, 'learned.instincts.yaml');
    const corrupt = 'instincts:\n  bad:\n    rule: "\\.eml$"\n';
    await writeFile(path, corrupt, 'utf-8');

    await expect(loader.append('learned.instincts.yaml', instinct('newcomer'))).rejects.toThrow();

    // The unparseable file is still there, byte for byte.
    expect(await readFile(path, 'utf-8')).toBe(corrupt);
  });

  it('throws instead of overwriting when the store path cannot be read', async () => {
    // A directory where the store file should be: the read fails with EISDIR,
    // which is not ENOENT, so append() must refuse rather than create a fresh
    // file. Deliberately not a chmod 000 file — root ignores the mode, and CI
    // runs as root, so that variant passes locally and fails in the container.
    await mkdir(join(dir, 'learned.instincts.yaml'));

    await expect(
      loader.append('learned.instincts.yaml', instinct('newcomer')),
    ).rejects.toThrow(/could not be loaded/);

    // Still a directory — nothing was written over it.
    expect((await stat(join(dir, 'learned.instincts.yaml'))).isDirectory()).toBe(true);
  });
});

describe('InstinctLoader.save — atomic', () => {
  it('leaves no partial file behind when serialization fails', async () => {
    const path = join(dir, 'learned.instincts.yaml');
    const original = stringify({ version: '1.0', instincts: { keep: instinct('keep') } });
    await writeFile(path, original, 'utf-8');

    // confidence out of range: rejected by the schema inside save()
    const bad = { version: '1.0' as const, instincts: { broken: { ...instinct('broken'), confidence: 42 } } };
    await expect(loader.save('learned.instincts.yaml', bad as never)).rejects.toThrow();

    expect(await readFile(path, 'utf-8')).toBe(original);
  });
});
